import path from 'path';
import os from 'os';
import fs from 'fs';
import net from 'net';
import { simpleGit, type SimpleGit } from 'simple-git';
import { spawn, type ChildProcess } from 'child_process';
import { createLogger } from '../utils/logger';
import { subprocessEnvironment } from '../utils/subprocessEnvironment';
import { loadDesignSystemMarkdown } from './templates/designCatalog';
import {
  writeTemplateBundle,
  type TemplateBundle,
} from './templates/viteReactTs';
import type { DesignContextEntry } from '../agent-variants/contracts';
import {
  DevServerStartError,
  isCompilationFailureOutput,
  isPortInUseOutput,
  type DevServerFailureReason,
} from '../utils/devServerError';
import { findAvailablePort, probeLoopbackHttp } from '../utils/portUtils';
import { INTERNAL_GIT_IDENTITY_ARGS } from '../utils/internalGitIdentity';
import {
  isPathStrictlyInsideRoot,
  isPathWithinRoot,
  resolveRealPathWithinRoot,
} from '../utils/pathContainment';
import { isInstallOutputPath } from './ProjectPackageManager';
import {
  selectedOperatingSystemServices,
  type OperatingSystemServices,
} from './OperatingSystemServices';
import { errnoCode } from '../utils/errnoCode';
import { errorMessage } from '../utils/errorMessage';
import { failureReasonCode } from '../utils/failureReason';
import { runGitCommand } from './GitCommandError';
import type { WorktreeCreationOptions } from '../agent-variants/variant-project-runtime';

const log = createLogger('WorktreeManager');
const DEV_SERVER_READY_INACTIVITY_MS = 30_000;
const DEV_SERVER_READY_MAX_MS = 120_000;
const DEV_SERVER_PROBE_TIMEOUT_MS = 1_000;
const DEV_SERVER_OUTPUT_TAIL_LIMIT = 4_000;
const GIT_BLOCK_TIMEOUT_MS = 120_000;
const GIT_OPTS = { timeout: { block: GIT_BLOCK_TIMEOUT_MS } } as const;
const SNAPSHOT_EXCLUDES = ['.rivet/', 'node_modules/'];
const EXISTING_WORKTREE_BASE = '/tmp';
export const FRESH_WORKTREES_DIRNAME = '.rivet-variants';
const WORKTREE_PREFIX = 'rivet-variants';
const SESSION_ID_PATTERN = /^[A-Za-z0-9_-]+$/;
export const INSTANCE_PREFIX = `${WORKTREE_PREFIX}-pid${process.pid}`;

const FRESH_ROOTS_REGISTRY_PATH = path.join(
  os.homedir(),
  '.rivet',
  'fresh-worktree-roots.json',
);

const FRESH_SESSION_ERROR =
  'Fresh-project sessions have no source project — this operation requires an existing project path.';

export class WorktreeManager {
  private readonly resolveProjectPath: () => string | null;

  private readonly reservedPorts = new Set<number>();

  constructor(
    projectPath: string | null | (() => string | null),
    private readonly operatingSystemServices: OperatingSystemServices = selectedOperatingSystemServices,
  ) {
    if (typeof projectPath === 'function') {
      this.resolveProjectPath = projectPath;
    } else {
      const value = projectPath;
      this.resolveProjectPath = () => value;
    }
  }

  private get projectPath(): string {
    const resolved = this.resolveProjectPath();
    if (!resolved) {
      throw new Error(FRESH_SESSION_ERROR);
    }
    return resolved;
  }

  async getGitRoot(): Promise<string> {
    const root = await simpleGit(this.projectPath, GIT_OPTS).revparse([
      '--show-toplevel',
    ]);
    return root.trim();
  }

  private async realPath(p: string): Promise<string> {
    try {
      return await fs.promises.realpath(p);
    } catch {
      return path.resolve(p);
    }
  }

  async ensureGitRepo(): Promise<void> {
    const projectPath = this.projectPath;
    const git = simpleGit(projectPath, GIT_OPTS);
    const insideRepo = await git
      .raw(['rev-parse', '--is-inside-work-tree'])
      .then((out) => out.trim() === 'true')
      .catch(() => false);
    const hasHead = insideRepo
      ? await git
          .raw(['rev-parse', '--verify', 'HEAD'])
          .then(() => true)
          .catch(() => false)
      : false;
    if (hasHead) return;

    if (!insideRepo) {
      log.info(`No git repo at ${projectPath} — initializing one for Rivet`);
      await runGitCommand('init', () => git.init());
      await this.excludeFromSnapshot(git);
    } else {
      log.info(
        `Git repo at ${projectPath} has no HEAD — creating one for Rivet`,
      );
    }
    await runGitCommand('add -A', () => git.add(['-A']));
    await runGitCommand('commit', () =>
      git.raw([
        '-c',
        'user.name=Rivet',
        '-c',
        'user.email=hello@tryrivet.design',
        'commit',
        '--allow-empty',
        '--no-gpg-sign',
        '-m',
        'rivet: initial',
      ]),
    );
  }

  private async excludeFromSnapshot(git: SimpleGit): Promise<void> {
    const excludePath = path.resolve(
      this.projectPath,
      (await git.raw(['rev-parse', '--git-path', 'info/exclude'])).trim(),
    );
    await fs.promises.mkdir(path.dirname(excludePath), { recursive: true });
    await fs.promises.appendFile(
      excludePath,
      `${SNAPSHOT_EXCLUDES.join('\n')}\n`,
    );
  }

  async getProjectCwdInWorktree(worktreePath: string): Promise<string> {
    const gitRoot = await this.realPath(await this.getGitRoot());
    const projectPath = await this.realPath(this.projectPath);
    const relPath = path.relative(gitRoot, projectPath);
    if (!isPathWithinRoot(gitRoot, projectPath)) {
      log.warn(
        `getProjectCwdInWorktree: projectPath ${projectPath} is outside git root ${gitRoot} (rel=${relPath}); falling back to worktreePath`,
      );
      return worktreePath;
    }
    return relPath ? path.join(worktreePath, relPath) : worktreePath;
  }

  async translateToWorktreePath(
    absPath: string,
    worktreePath: string,
  ): Promise<string> {
    const gitRoot = await this.realPath(await this.getGitRoot());
    const realAbsPath = await this.realPath(absPath);
    if (!isPathWithinRoot(gitRoot, realAbsPath)) return absPath;
    return path.join(worktreePath, path.relative(gitRoot, realAbsPath));
  }

  async getUncommittedPatch(): Promise<string> {
    const git = simpleGit(this.projectPath, GIT_OPTS);
    const diff = await git.diff(['--binary', '--full-index', 'HEAD']);
    return diff;
  }

  private async getUntrackedFiles(): Promise<string[]> {
    const gitRoot = await this.getGitRoot();
    const git = simpleGit(gitRoot, GIT_OPTS);
    const result = await git.raw([
      'ls-files',
      '--others',
      '--exclude-standard',
      '-z',
    ]);
    return result.split('\0').filter(Boolean);
  }

  private async toGitRootRelativeFiles(
    gitRoot: string,
    projectFiles: readonly string[],
  ): Promise<string[]> {
    if (projectFiles.length === 0) return [];
    const realGitRoot = await this.realPath(gitRoot);
    const realProjectPath = await this.realPath(this.projectPath);
    const relativeFiles: string[] = [];
    for (const projectFile of projectFiles) {
      const filePath = path.join(realProjectPath, projectFile);
      if (
        !isPathStrictlyInsideRoot(realGitRoot, filePath) ||
        !fs.existsSync(filePath)
      )
        continue;
      const realFilePath = await resolveRealPathWithinRoot({
        root: realProjectPath,
        candidate: filePath,
        containment: 'strict',
      });
      if (!realFilePath) {
        log.warn(
          `Left ${projectFile} out of the variant worktrees because it resolves outside the project`,
        );
        continue;
      }
      relativeFiles.push(path.relative(realGitRoot, filePath));
    }
    return relativeFiles;
  }

  private copyFilesIntoWorktree(
    relativePaths: string[],
    gitRoot: string,
    worktreePath: string,
  ): void {
    for (const relPath of relativePaths) {
      try {
        const src = path.join(gitRoot, relPath);
        const dest = path.join(worktreePath, relPath);
        fs.mkdirSync(path.dirname(dest), { recursive: true });
        fs.copyFileSync(src, dest, fs.constants.COPYFILE_FICLONE);
      } catch (err) {
        if (errnoCode(err) === 'ENOENT') {
          log.warn(`Skipped untracked file ${relPath} with no readable source`);
          continue;
        }
        throw new Error(
          `Could not copy untracked file ${relPath} to worktree: ${errorMessage(err)}`,
        );
      }
    }
  }

  private async commitDetachedBaseline(
    worktreeGit: SimpleGit,
    message: string,
  ): Promise<void> {
    const tree = (await worktreeGit.raw(['write-tree'])).trim();
    const baseline = (
      await worktreeGit.raw([
        ...INTERNAL_GIT_IDENTITY_ARGS,
        'commit-tree',
        tree,
        '-p',
        'HEAD',
        '-m',
        message,
      ])
    ).trim();
    await worktreeGit.raw(['update-ref', '--no-deref', 'HEAD', baseline]);
  }

  private applyPatchViaStdin(patch: string, cwd: string): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const cp = spawn('git', ['apply', '--whitespace=nowarn', '-'], {
        env: subprocessEnvironment('git'),
        cwd,
        stdio: ['pipe', 'pipe', 'pipe'],
      });
      let stderr = '';
      cp.stderr.on('data', (d: Buffer) => {
        stderr += d.toString();
      });
      cp.on('close', (code: number) => {
        if (code !== 0) reject(new Error(`git apply failed: ${stderr}`));
        else resolve();
      });
      cp.stdin.write(patch);
      cp.stdin.end();
    });
  }

  async createWorktrees(
    sessionId: string,
    count: number,
    instanceKeyPrefix = '',
    options: WorktreeCreationOptions = {},
  ): Promise<string[]> {
    this.assertSafeSessionId(sessionId);
    if (instanceKeyPrefix && !SESSION_ID_PATTERN.test(instanceKeyPrefix)) {
      throw new Error(
        'Invalid instanceKeyPrefix: expected a safe path segment',
      );
    }
    await this.ensureGitRepo();
    const git = simpleGit(this.projectPath, GIT_OPTS);
    const patch = await runGitCommand('diff HEAD', () =>
      this.getUncommittedPatch(),
    );
    const gitRoot = await runGitCommand('rev-parse --show-toplevel', () =>
      this.getGitRoot(),
    );
    const untrackedFiles = await runGitCommand('ls-files --others', () =>
      this.getUntrackedFiles(),
    );
    const requiredFiles = await this.toGitRootRelativeFiles(
      gitRoot,
      options.requiredProjectFiles ?? [],
    );
    const paths: string[] = [];

    for (let i = 0; i < count; i++) {
      const worktreePath = path.join(
        EXISTING_WORKTREE_BASE,
        `${INSTANCE_PREFIX}-${sessionId}-${instanceKeyPrefix}${i}`,
      );
      let isWorktreeCreated = false;
      try {
        await git.raw(['worktree', 'add', '--detach', worktreePath, 'HEAD']);
        isWorktreeCreated = true;

        if (patch.trim()) {
          await this.applyPatchViaStdin(patch, worktreePath);
        }

        if (untrackedFiles.length > 0) {
          this.copyFilesIntoWorktree(untrackedFiles, gitRoot, worktreePath);
        }

        const ignoredRequiredFiles = requiredFiles.filter(
          (relPath) => !fs.existsSync(path.join(worktreePath, relPath)),
        );
        this.copyFilesIntoWorktree(ignoredRequiredFiles, gitRoot, worktreePath);

        const wtGit = simpleGit(worktreePath, GIT_OPTS);
        if (ignoredRequiredFiles.length > 0) {
          await wtGit.raw(['add', '--force', '--', ...ignoredRequiredFiles]);
        }
        await wtGit.raw(['add', '-A']);
        await this.commitDetachedBaseline(wtGit, 'rivet: variant baseline');

        paths.push(worktreePath);
      } catch (e) {
        const incompletePaths = isWorktreeCreated
          ? [...paths, worktreePath]
          : paths;
        for (const incompletePath of incompletePaths) {
          try {
            await git.raw(['worktree', 'remove', '--force', incompletePath]);
          } catch (cleanupError) {
            log.warn(
              'Could not unregister an incomplete variant worktree',
              cleanupError,
            );
            await fs.promises.rm(incompletePath, {
              recursive: true,
              force: true,
            });
          }
        }
        log.error(`Failed to create worktree ${i}:`, e);
        const msg = errorMessage(e);
        if (/block timeout reached/i.test(msg)) {
          throw new Error(
            `git stalled while provisioning variant worktree ${i} (no output for ${GIT_BLOCK_TIMEOUT_MS / 1000}s). ` +
              `This usually means a very large working tree (e.g. a React Native project with native build dirs ` +
              `under ios/android that aren't git-ignored) or a wedged git process. ` +
              `Consider .gitignoring build artifacts before generating variants.`,
          );
        }
        throw e;
      }
    }
    return paths;
  }

  async forkWorktreesFrom(
    sourceWorktreePath: string,
    sessionId: string,
    count: number,
    instanceKeyPrefix = '',
  ): Promise<string[]> {
    this.assertSafeSessionId(sessionId);
    if (instanceKeyPrefix && !SESSION_ID_PATTERN.test(instanceKeyPrefix)) {
      throw new Error(
        'Invalid instanceKeyPrefix: expected a safe path segment',
      );
    }
    const resolvedSource = path.resolve(sourceWorktreePath);
    if (!fs.existsSync(resolvedSource)) {
      throw new Error(
        `Cannot fork worktrees: source path does not exist (${resolvedSource})`,
      );
    }
    const paths: string[] = [];
    for (let i = 0; i < count; i++) {
      const worktreePath = path.join(
        EXISTING_WORKTREE_BASE,
        `${INSTANCE_PREFIX}-${sessionId}-${instanceKeyPrefix}${i}`,
      );
      fs.mkdirSync(path.dirname(worktreePath), { recursive: true });
      await fs.promises.cp(resolvedSource, worktreePath, {
        recursive: true,
        verbatimSymlinks: true,
        mode: fs.constants.COPYFILE_FICLONE,
        filter: (source) =>
          !isInstallOutputPath(path.relative(resolvedSource, source)),
      });
      paths.push(worktreePath);
    }
    return paths;
  }

  async getDiff(worktreePath: string): Promise<string> {
    const git = simpleGit(worktreePath);
    await git.raw(['add', '--intent-to-add', '.']).catch(() => {});
    return git.diff(['--binary', '--full-index', 'HEAD']);
  }

  async getChangedFiles(worktreePath: string): Promise<string[]> {
    const git = simpleGit(worktreePath, GIT_OPTS);
    await git.raw(['add', '--intent-to-add', '.']).catch(() => {});
    const names = await git.raw([
      'diff',
      '--name-only',
      '--diff-filter=d',
      '-z',
      'HEAD',
    ]);
    return names.split('\0').filter(Boolean);
  }

  getFreePort(): Promise<number> {
    return new Promise<number>((resolve, reject) => {
      const server = net.createServer();
      server.listen(0, () => {
        const addr = server.address();
        const port = addr && typeof addr === 'object' ? addr.port : 0;
        server.close(() => resolve(port));
      });
      server.on('error', reject);
    });
  }

  async findFreePortFrom(startPort: number, scanWindow = 64): Promise<number> {
    const base =
      Number.isInteger(startPort) && startPort > 0 && startPort <= 65535
        ? startPort
        : 3000;
    const limit = Math.min(65535, base + scanWindow - 1);
    let from = base;
    while (from <= limit) {
      let candidate: number;
      try {
        candidate = await findAvailablePort(from);
      } catch {
        break;
      }
      if (candidate > limit) break;
      if (!this.reservedPorts.has(candidate)) {
        this.reservedPorts.add(candidate);
        return candidate;
      }
      from = candidate + 1;
    }
    const fallback = await this.getFreePort();
    this.reservedPorts.add(fallback);
    return fallback;
  }

  releasePort(port: number): void {
    this.reservedPorts.delete(port);
  }

  validateDiff(diff: string, reverse: boolean): Promise<void> {
    if (!diff.trim()) return Promise.resolve();
    return new Promise<void>((resolve, reject) => {
      const args = ['apply', '--check', '--whitespace=nowarn'];
      if (reverse) args.push('--reverse');
      args.push('-');
      const cp = spawn('git', args, {
        env: subprocessEnvironment('git'),
        cwd: this.projectPath,
        stdio: ['pipe', 'pipe', 'pipe'],
      });
      let stderr = '';
      cp.stderr.on('data', (d: Buffer) => {
        stderr += d.toString();
      });
      cp.on('close', (code: number) => {
        if (code !== 0)
          reject(new Error(`Diff validation failed: ${stderr.trim()}`));
        else resolve();
      });
      cp.stdin.write(diff);
      cp.stdin.end();
    });
  }

  async startDevServer(
    worktreePath: string,
    port: number,
    cmd: string,
    args: string[],
    env: Record<string, string>,
  ): Promise<ChildProcess> {
    const proc = this.operatingSystemServices.projectProcesses.start(
      { executable: cmd, args },
      {
        cwd: worktreePath,
        env: {
          ...subprocessEnvironment('devServer'),
          NODE_ENV: 'development',
          ...env,
        },
        stdio: 'pipe',
        detached: false,
      },
    );

    let outputTail = '';
    let lastOutputAt = Date.now();
    const drain = (data: Buffer) => {
      outputTail = (outputTail + data.toString()).slice(
        -DEV_SERVER_OUTPUT_TAIL_LIMIT,
      );
      lastOutputAt = Date.now();
      log.debug(`[variant-dev:${port}] ${data.toString().trim()}`);
    };
    proc.stdout?.on('data', drain);
    proc.stderr?.on('data', drain);

    const term: {
      exited?: { code: number | null; signal: NodeJS.Signals | null };
      spawnError?: Error;
    } = {};
    const onExit = (code: number | null, signal: NodeJS.Signals | null) => {
      term.exited = { code, signal };
    };
    const onError = (err: Error) => {
      term.spawnError = err;
      log.warn(`Dev server error (port ${port}):`, err);
    };
    proc.once('exit', onExit);
    proc.once('error', onError);
    const detach = () => {
      proc.off('exit', onExit);
      proc.off('error', onError);
    };

    const fail = (reason: DevServerFailureReason): never => {
      detach();
      const portInUse = isPortInUseOutput(outputTail);
      const detail = outputTail.trim();
      const failureReason =
        reason !== 'spawn_error' && isCompilationFailureOutput(detail)
          ? 'compile_error'
          : reason;
      let message: string;
      if (failureReason === 'compile_error') {
        message = `Dev server could not compile the preview on port ${port}`;
      } else if (reason === 'spawn_error') {
        message = `Dev server failed to spawn on port ${port}: ${
          term.spawnError?.message ?? 'unknown error'
        }`;
      } else if (reason === 'exited') {
        message = `Dev server exited before becoming ready on port ${port} (code=${
          term.exited?.code ?? 'null'
        }, signal=${term.exited?.signal ?? 'null'}${
          portInUse ? ', port already in use' : ''
        })`;
      } else {
        message = `Dev server on port ${port} did not become ready (silent for ${
          DEV_SERVER_READY_INACTIVITY_MS / 1000
        }s or exceeded the ${DEV_SERVER_READY_MAX_MS / 1000}s ceiling)`;
      }
      throw new DevServerStartError({
        message: detail ? `${message}\n${detail}` : message,
        reason: failureReason,
        portInUse,
        detail,
        exitCode: term.exited?.code ?? null,
        signal: term.exited?.signal ?? null,
        reasonCode: term.spawnError
          ? failureReasonCode(term.spawnError)
          : undefined,
        summary: term.spawnError ? message : undefined,
      });
    };

    const hardDeadline = Date.now() + DEV_SERVER_READY_MAX_MS;
    while (
      Date.now() <
      Math.min(hardDeadline, lastOutputAt + DEV_SERVER_READY_INACTIVITY_MS)
    ) {
      if (term.spawnError) fail('spawn_error');
      if (term.exited) fail('exited');
      const isReady = await probeLoopbackHttp(port, {
        timeoutMs: DEV_SERVER_PROBE_TIMEOUT_MS,
      });
      if (term.spawnError) fail('spawn_error');
      if (term.exited) fail('exited');
      if (isReady) {
        detach();
        return proc;
      }
      if (isCompilationFailureOutput(outputTail)) {
        await this.stopDevServer(proc);
        fail('compile_error');
      }
      await new Promise((r) => setTimeout(r, 500));
    }

    if (term.spawnError) fail('spawn_error');
    if (term.exited) fail('exited');
    try {
      await this.operatingSystemServices.projectProcesses.terminate(proc, {
        isForceful: true,
      });
    } catch {}
    return fail('timeout');
  }

  async stopDevServer(proc: ChildProcess, timeoutMs = 5_000): Promise<void> {
    if (proc.killed || proc.exitCode !== null || proc.pid == null) return;

    const exited = new Promise<void>((resolve) => {
      const done = () => {
        proc.off('exit', done);
        proc.off('error', done);
        resolve();
      };
      proc.once('exit', done);
      proc.once('error', done);
    });

    try {
      await this.operatingSystemServices.projectProcesses.terminate(proc, {
        isForceful: false,
      });
    } catch {}

    let timeout: ReturnType<typeof setTimeout> | undefined;
    const timedOut = await Promise.race([
      exited.then(() => false),
      new Promise<boolean>((resolve) => {
        timeout = setTimeout(() => resolve(true), timeoutMs);
      }),
    ]);
    if (timeout) {
      clearTimeout(timeout);
    }

    if (!timedOut) return;

    try {
      await this.operatingSystemServices.projectProcesses.terminate(proc, {
        isForceful: true,
      });
    } catch {}
    await exited;
  }

  async cleanupSession(
    sessionId: string,
    freshDestinationParent?: string,
  ): Promise<void> {
    this.assertSafeSessionId(sessionId);
    if (!this.resolveProjectPath()) {
      if (freshDestinationParent) {
        this.cleanupFreshWorktrees(sessionId, freshDestinationParent);
      }
      return;
    }
    const git = simpleGit(this.projectPath, GIT_OPTS);
    const pattern = path.join(
      EXISTING_WORKTREE_BASE,
      `${INSTANCE_PREFIX}-${sessionId}-`,
    );
    try {
      const worktreeList = await git.raw(['worktree', 'list', '--porcelain']);
      const worktreePaths = worktreeList
        .split('\n')
        .filter((line) => line.startsWith('worktree '))
        .map((line) => line.replace('worktree ', '').trim())
        .filter((p) => p.startsWith(pattern));

      for (const wPath of worktreePaths) {
        try {
          await git.raw(['worktree', 'remove', '--force', wPath]);
        } catch {
          fs.rmSync(wPath, { recursive: true, force: true });
        }
      }
    } catch (e) {
      log.warn('Worktree cleanup error:', e);
    }
    if (freshDestinationParent) {
      this.cleanupFreshWorktrees(sessionId, freshDestinationParent);
    }
  }

  async createFreshWorktrees(
    sessionId: string,
    count: number,
    template: TemplateBundle,
    designContext: ReadonlyArray<DesignContextEntry | undefined> | undefined,
    destinationParent: string,
  ): Promise<string[]> {
    this.assertSafeSessionId(sessionId);
    if (!destinationParent || !path.isAbsolute(destinationParent)) {
      throw new Error(
        'createFreshWorktrees requires an absolute destinationParent path',
      );
    }
    const freshRoot = path.join(destinationParent, FRESH_WORKTREES_DIRNAME);
    fs.mkdirSync(freshRoot, { recursive: true });
    registerFreshWorktreeRoot(freshRoot);
    const paths: string[] = [];
    for (let i = 0; i < count; i++) {
      const worktreePath = path.join(
        freshRoot,
        `${INSTANCE_PREFIX}-${sessionId}-${i}`,
      );
      fs.mkdirSync(worktreePath, { recursive: true });
      writeTemplateBundle(template, worktreePath);

      this.writeDesignContext(worktreePath, i, designContext?.[i]);

      const wtGit = simpleGit(worktreePath, GIT_OPTS);
      try {
        await wtGit.raw(['init']);
        await wtGit.raw(['add', '-A']);
        await wtGit
          .raw([
            '-c',
            'user.name=Rivet',
            '-c',
            'user.email=hello@tryrivet.design',
            'commit',
            '--no-gpg-sign',
            '-m',
            'rivet: variant baseline',
          ])
          .catch((err) => {
            log.warn(`Fresh worktree ${i}: baseline commit failed`, err);
          });
      } catch (err) {
        log.warn(`Fresh worktree ${i}: git init failed`, err);
      }

      paths.push(worktreePath);
    }
    return paths;
  }

  private writeDesignContext(
    worktreePath: string,
    slot: number,
    entry: DesignContextEntry | undefined,
  ): void {
    if (!entry) return;
    if (entry.kind === 'markdown') {
      const label = entry.label.replace(/-->/g, '-- >');
      fs.writeFileSync(
        path.join(worktreePath, 'DESIGN.md'),
        `<!-- Custom design context: ${label} -->\n\n${entry.content}`,
        'utf8',
      );
      return;
    }

    const markdown = loadDesignSystemMarkdown(entry.slug);
    if (markdown) {
      fs.writeFileSync(path.join(worktreePath, 'DESIGN.md'), markdown, 'utf8');
      return;
    }
    log.warn(
      `Fresh worktree ${slot}: unknown design system slug '${entry.slug}' — DESIGN.md skipped`,
    );
  }

  cleanupFreshWorktrees(
    sessionId: string,
    destinationParent: string,
    preserve?: ReadonlySet<string>,
  ): void {
    this.assertSafeSessionId(sessionId);
    if (!destinationParent || !path.isAbsolute(destinationParent)) {
      log.warn(
        'cleanupFreshWorktrees: destinationParent missing or not absolute — skipping',
      );
      return;
    }
    const freshRoot = path.join(destinationParent, FRESH_WORKTREES_DIRNAME);
    try {
      const prefix = `${INSTANCE_PREFIX}-${sessionId}-`;
      const entries = fs
        .readdirSync(freshRoot)
        .filter((e) => e.startsWith(prefix))
        .filter((e) => !preserve?.has(e));
      for (const entry of entries) {
        fs.rmSync(path.join(freshRoot, entry), {
          recursive: true,
          force: true,
        });
      }
      try {
        const remaining = fs.readdirSync(freshRoot);
        if (remaining.length === 0) {
          fs.rmdirSync(freshRoot);
        }
      } catch {}
    } catch (e) {
      if ((e as { code?: string }).code !== 'ENOENT') {
        log.warn('Fresh worktree cleanup error:', e);
      }
    }
  }

  private assertSafeSessionId(sessionId: string): void {
    if (!SESSION_ID_PATTERN.test(sessionId)) {
      throw new Error('Invalid sessionId: expected a safe path segment');
    }
  }
}

const loadFreshWorktreeRoots = (): string[] => {
  try {
    const raw = fs.readFileSync(FRESH_ROOTS_REGISTRY_PATH, 'utf8');
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter((p): p is string => typeof p === 'string');
  } catch {
    return [];
  }
};

const saveFreshWorktreeRoots = (roots: string[]): void => {
  try {
    fs.mkdirSync(path.dirname(FRESH_ROOTS_REGISTRY_PATH), { recursive: true });
    const deduped = Array.from(new Set(roots));
    fs.writeFileSync(
      FRESH_ROOTS_REGISTRY_PATH,
      JSON.stringify(deduped, null, 2),
      'utf8',
    );
  } catch (err) {
    if (['EACCES', 'EPERM'].includes((err as { code?: string }).code ?? '')) {
      return;
    }
    log.warn('Could not persist fresh-worktree-roots registry:', err);
  }
};

export const registerFreshWorktreeRoot = (freshRoot: string): void => {
  const existing = loadFreshWorktreeRoots();
  if (existing.includes(freshRoot)) return;
  existing.push(freshRoot);
  saveFreshWorktreeRoots(existing);
};

export const cleanupOrphanedWorktrees = () => {
  try {
    const entries = fs
      .readdirSync(EXISTING_WORKTREE_BASE)
      .filter((e) => e.startsWith(INSTANCE_PREFIX));
    for (const entry of entries) {
      fs.rmSync(path.join(EXISTING_WORKTREE_BASE, entry), {
        recursive: true,
        force: true,
      });
    }
  } catch {}

  const roots = loadFreshWorktreeRoots();
  const survivingRoots: string[] = [];
  for (const root of roots) {
    let rootStillExists = true;
    try {
      const entries = fs
        .readdirSync(root)
        .filter((e) => e.startsWith(INSTANCE_PREFIX));
      for (const entry of entries) {
        fs.rmSync(path.join(root, entry), { recursive: true, force: true });
      }
    } catch (err) {
      if ((err as { code?: string }).code === 'ENOENT') {
        rootStillExists = false;
      }
    }
    if (rootStillExists) survivingRoots.push(root);
  }
  if (survivingRoots.length !== roots.length) {
    saveFreshWorktreeRoots(survivingRoots);
  }
};

process.on('exit', cleanupOrphanedWorktrees);

export const pruneWorktrees = async (projectPath: string): Promise<void> => {
  try {
    await simpleGit(projectPath, GIT_OPTS).raw(['worktree', 'prune']);
  } catch {}
};
